<template>
    <div class="header-main">
        <div class="w">
            <div class="row justify-content-between">
                <div class="logo col col-md-3 " @click="recover">
                    <!-- <img src="../assets/img/logo.png" alt=""> -->
                    <img src="../assets/logo.png" alt="">
                    <h4 id="company">Techtron</h4>
                </div>

                <div class="lang col col-md-3">
                    <select class="form-select" aria-label="Default select example" v-model="lang">
                        <option value="1">{{ $t('language.zh') }}</option>
                        <option value="2">{{ $t('language.en') }}</option>
                    </select>
                </div>
                <!-- <div class="logo col col-md-6" >
                    <ul id="menu">
                        <li><a href="javascript:void(0)" @click="activeMenu('proj')" id="proj">项目中心</a></li>
                        <li><a href="javascript:void(0)" @click="activeMenu('team')" id="team">团队风采</a></li>
                        <li><a href="javascript:void(0)" @click="activeMenu('culture')" id="culture">企业文化</a></li>
                    </ul>
                </div> -->
            </div>


        </div>

    </div>
</template>

<script>
export default {
    computed: {
        lang: {
            get() {
                let rout  = this.$route.name;
                if(rout.includes('en')) {
                    this.$i18n.locale = 'en';
                    return 2;
                }
                else {
                    this.$i18n.locale = 'zh';
                    return 1;
                }
            },
            set(val) {
                if (val !== this.lang) {
                    if (val == 2) {
                        this.changeEng();
                    } else {
                        this.changeZh();
                    }
                }

            }
        }
    },
    methods: {
        activeMenu(id) {
            let lis = document.querySelectorAll('ul#menu a');
            lis.forEach(v => {
                v.classList.remove('a_active');
            })
            let menu = document.getElementById(id);
            menu.classList.add('a_active');
            this.$emit("scroll", id);
        },
        recover() {
            window.scroll(0, 0);
        },
        changeEng() {
            this.$i18n.locale = 'en',
             this.$route.path !== '/home-en' && this.$router.push({ path: "/home-en" });
        },
        // 选择中文
        changeZh() {
            this.$i18n.locale = 'zh',
            this.$route.path !== '/home-zh' && this.$router.push({ path: "/home-zh" });
        },
    },

}
</script>

<style>
.header-main {
    width: 100%;
    height: 70px;
    position: sticky;
    top: 0;
    z-index: 999;
    background-color: #333;
}

.row {
    margin: 0 auto;
}

.w {
    max-width: 1200px;
    height: 100%;
    margin: 0 auto;
}

.logo img {
    height: 100%;
    padding: 8px 0;
    float: left;
}

.logo {
    cursor: pointer;
    height: 70px;
}

#menu {
    display: flex;
    margin: 0;
}

#menu li {
    flex: 1;
    height: 70px;
    line-height: 70px;
    display: block;
    text-align: center;
}

#menu li a {
    font-size: 16px;
    color: #666;
    display: block;
    margin: 0 10px;
    height: 100%;
}

a {
    -webkit-tap-highlight-color: rgba(0, 0, 0, 0);
    -webkit-tap-highlight-color: transparent;
    text-decoration: none;
}

#menu li a:hover {
    color: #498F9F;
    border-bottom: 2px solid #498F9F;
}

.a_active {
    color: #498F9F !important;
    border-bottom: 2px solid #498F9F;
}

.lang {
    padding-top: 20px;
}
#company{ 
    float: left;
    padding: 20px 5px 5px 5px;
    border-bottom: 2px solid #3c88d5;
    color: #fff;
    font-family: fangsong;
    font-weight: 700;
}
</style>